/**
 * MESX System Design Library
 *
 * Exports design tokens, components, and styles for MES X.0 projects.
 */

// Design tokens (JS)
// CSS variables & global styles (side-effect import)
import './styles/variables.css';

export * from './tokens/index';

// Vue components
export * from './components/index';

import { Quasar } from 'quasar';
import { createApp } from 'vue';
import app from './app.vue';
import './styles/variables.css';

const application = createApp(app);

application.use(Quasar, {
  plugins: {},
});

application.mount('#app');

/** Design tokens exported as JS constants for programmatic usage. */

export const colors = {
  accent: '#9C27B0',
  dark: '#1D1D1D',
  info: '#31CCEC',
  negative: '#C10015',
  positive: '#21BA45',
  primary: '#1976D2',
  secondary: '#26A69A',
  warning: '#F2C037',
} as const;

export const spacing = {
  lg: '24px',
  md: '16px',
  sm: '8px',
  xl: '32px',
  xs: '4px',
} as const;

export const fontSizes = {
  lg: '1.25rem',
  md: '1rem',
  sm: '0.875rem',
  xl: '1.5rem',
  xs: '0.75rem',
} as const;

export const radii = {
  full: '9999px',
  lg: '16px',
  md: '8px',
  sm: '4px',
} as const;

/// <reference types="vite/client" />

declare module '*.vue' {
  import type { DefineComponent } from 'vue';

  const component: DefineComponent<object, object, unknown>;
  export default component;
}

